package data_structures.linear;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class LinkedList {
public static class LinkedListNode<T>{public T value;public LinkedListNode<T> next;public LinkedListNode(T value){this.value=value;}}public static class ListImpl<T> implements Iterable<T>{private LinkedListNode<T> head,tail;private int length;public static <T> ListImpl<T> from(Iterable<T> values){ListImpl<T> l=new ListImpl<>();for(T v:values)l.append(v);return l;}public int size(){return length;}public T first(){return head==null?null:head.value;}public T last(){return tail==null?null:tail.value;}public ListImpl<T> append(T v){LinkedListNode<T> n=new LinkedListNode<>(v);if(tail==null)head=n;else tail.next=n;tail=n;length++;return this;}public ListImpl<T> prepend(T v){LinkedListNode<T> n=new LinkedListNode<>(v);n.next=head;head=n;if(tail==null)tail=n;length++;return this;}private LinkedListNode<T> nodeAt(int i){LinkedListNode<T> n=head;while(i-->0)n=n.next;return n;}public ListImpl<T> insertAt(int i,T v){if(i<0||i>length)throw new IndexOutOfBoundsException();if(i==0)return prepend(v);if(i==length)return append(v);LinkedListNode<T> p=nodeAt(i-1),n=new LinkedListNode<>(v);n.next=p.next;p.next=n;length++;return this;}public T get(int i){return i<0||i>=length?null:nodeAt(i).value;}public int indexOf(T v){int i=0;for(T x:this){if(Objects.equals(x,v))return i;i++;}return -1;}public T find(Predicate<T> p){for(T x:this)if(p.test(x))return x;return null;}public T removeAt(int i){if(i<0||i>=length)return null;LinkedListNode<T> n;if(i==0){n=head;head=n.next;if(head==null)tail=null;}else{LinkedListNode<T> p=nodeAt(i-1);n=p.next;p.next=n.next;if(n==tail)tail=p;}length--;return n.value;}public boolean remove(T v){int i=indexOf(v);if(i<0)return false;removeAt(i);return true;}public ListImpl<T> reverse(){LinkedListNode<T> p=null,c=head;tail=head;while(c!=null){LinkedListNode<T> n=c.next;c.next=p;p=c;c=n;}head=p;return this;}public List<T> toArray(){List<T> o=new ArrayList<>();for(T v:this)o.add(v);return o;}public Iterator<T> iterator(){return new Iterator<>(){LinkedListNode<T> current=head;public boolean hasNext(){return current!=null;}public T next(){if(current==null)throw new NoSuchElementException();T v=current.value;current=current.next;return v;}};}}
}
